#include <iostream>
#include <string>
#include <sstream>
#include <unordered_set>
using namespace std;

unordered_set<char> vowels{'a', 'e', 'i', 'o', 'u'};

int maxVowels(string s, int k) {
	int ans = 0, cnt = 0;

	// first slide
	for (int i = 0; i < k; i++) {
		if (vowels.count(s[i])) {
			cnt++;
		}
	}
	ans = cnt;
	if (ans == k) return ans;

	for (int i = k; i < s.size(); i++) {
		cout << "Slide [" << i - k + 1 << "," << i << "]";
		if (vowels.count(s[i - k])) cnt--;
		if (vowels.count(s[i])) cnt++;
		cout << ", cnt = " << cnt << "\n";
		ans = max(ans, cnt);
		if (ans == k) return ans;
	}

	return ans;
}

