int main() {
	string s;
	while (getline(cin, s)) {
		if (s.find_first_not_of(" \t") == string::npos) continue;

		int k;
		cin >> k;

		cout << "ANS = " << maxVowels(s, k) << "\n";
	}

	return 0;
}